package admin

import (
	"embed"
	"io/fs"
	"net/http"
)

// The production console is generated by the Vue/Vite build. The fallback keeps
// source-only Go builds usable when the frontend toolchain has not been run.
//
//go:embed static/* fallback/*
var assets embed.FS

func Handler() http.Handler {
	content, err := fs.Sub(assets, "static")
	if err != nil {
		panic(err)
	}
	if _, err := fs.Stat(content, "index.html"); err != nil {
		content, err = fs.Sub(assets, "fallback")
		if err != nil {
			panic(err)
		}
	}
	return http.FileServer(http.FS(content))
}
